def _generate_key_id_sqlite() -> str:
    """Generate a 16-hex-char key id for SQLite (used in tests)."""
    # ``randomblob(8)`` returns 8 raw bytes; ``hex()`` gives 16 hex
    # chars. ``lower()`` keeps things consistent across engines.
    return "kid_" + sa.text("lower(hex(randomblob(8)))").compile()


